      if(el>=typeTotal&&!done){done=true; ts.textContent='done'; var c=tf.querySelector('.cur'); if(c) c.remove();}
      if(el<talkTotal){ kc.textContent=fmt(el); if(!reduce){wave.querySelectorAll('i').forEach(function(b){b.style.height=(4+Math.random()*24)+'px';});} }
