      if(sl&&!reduce){ sl.classList.add('out'); setTimeout(function(){ sl.classList.remove('out'); sl.classList.add('pre'); fill(i); requestAnimationFrame(function(){ requestAnimationFrame(function(){ sl.classList.remove('pre'); }); }); },200); } else { fill(i); }
